s = SRC.read_text(encoding="utf8")
for a, b in sorted(T, key=lambda p: -len(p[0])):  # longest first, so short phrases never split a longer sentence
    assert a in s, f"not found: {a[:60]}"
    s = s.replace(a, b)
# meta description / og text: replace whole content attributes
s = re.sub(r'(<meta name="description" content=")[^"]*', r"\1A private AI device for your office. Your team asks the company's files in Arabic and English over Wi-Fi — no internet, and no data leaves the building.", s)
s = re.sub(r'(<meta property="og:title" content=")[^"]*', r"\1InnerBrain — Your company's brain. Inside your company.", s)
s = re.sub(r'(<meta property="og:description" content=")[^"]*', r"\1Private AI that runs inside your office and knows your files. No per-user subscription, and your data never leaves.", s)
s = s.replace('<html lang="en" dir="ltr"', '<html lang="en" dir="ltr"', 1)
left = sorted(set(re.findall(r"[؀-ۿ][؀-ۿ\s،؛]*", re.sub(r'(?s)<link[^>]*hreflang="ar"[^>]*>|lang="ar">العربية', "", s))))
assert not left, f"untranslated Arabic left: {left[:10]}"
OUT.write_text(s, encoding="utf8")
print("wrote", OUT)
